package com.retronpcswapper.cache;

import java.util.Arrays;

public class RetroNpcDefinition
{
	private int id;
	private String name;
	private String description;
	private int size = 1;
	private int[] models;
	private int[] additionalModels;
	private int stanceAnimation = -1;
	private int walkAnimation = -1;
	private int turnAroundAnimation = -1;
	private int turnLeftAnimation = -1;
	private int turnRightAnimation = -1;
	private int combatLevel = -1;
	// Model resize in 1/128ths, as the 2005 client applied it (opcodes 97 and 98)
	private int scaleXZ = 128;
	private int scaleY = 128;
	private String[] actions = new String[5];
	private short[] originalColors;
	private short[] replacementColors;

	public int getId()
	{
		return id;
	}

	public void setId(int id)
	{
		this.id = id;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public String getDescription()
	{
		return description;
	}

	public void setDescription(String description)
	{
		this.description = description;
	}

	public int getSize()
	{
		return size;
	}

	public void setSize(int size)
	{
		this.size = size;
	}

	public int[] getModels()
	{
		return models != null ? models.clone() : new int[0];
	}

	public void setModels(int[] models)
	{
		this.models = models;
	}

	public int[] getAdditionalModels()
	{
		return additionalModels != null ? additionalModels.clone() : new int[0];
	}

	public void setAdditionalModels(int[] additionalModels)
	{
		this.additionalModels = additionalModels;
	}

	public int getStanceAnimation()
	{
		return stanceAnimation;
	}

	public void setStanceAnimation(int stanceAnimation)
	{
		this.stanceAnimation = stanceAnimation;
	}

	public int getWalkAnimation()
	{
		return walkAnimation;
	}

	public void setWalkAnimation(int walkAnimation)
	{
		this.walkAnimation = walkAnimation;
	}

	public int getScaleXZ()
	{
		return scaleXZ;
	}

	public void setScaleXZ(int scaleXZ)
	{
		this.scaleXZ = scaleXZ;
	}

	public int getScaleY()
	{
		return scaleY;
	}

	public void setScaleY(int scaleY)
	{
		this.scaleY = scaleY;
	}

	public int getCombatLevel()
	{
		return combatLevel;
	}

	public void setCombatLevel(int combatLevel)
	{
		this.combatLevel = combatLevel;
	}

	public String[] getActions()
	{
		return actions != null ? actions.clone() : new String[5];
	}

	public void setActions(String[] actions)
	{
		this.actions = actions;
	}

	public short[] getOriginalColors()
	{
		return originalColors != null ? originalColors.clone() : null;
	}

	public void setOriginalColors(short[] originalColors)
	{
		this.originalColors = originalColors;
	}

	public short[] getReplacementColors()
	{
		return replacementColors != null ? replacementColors.clone() : null;
	}

	public void setReplacementColors(short[] replacementColors)
	{
		this.replacementColors = replacementColors;
	}

	@Override
	public String toString()
	{
		return "RetroNpcDefinition{" +
			"id=" + id +
			", name='" + name + '\'' +
			", combatLevel=" + combatLevel +
			", models=" + Arrays.toString(models) +
			", stanceAnimation=" + stanceAnimation +
			", walkAnimation=" + walkAnimation +
			'}';
	}
}

