package com.retronpcswapper;

import lombok.Getter;

/**
 * One row of the bundled npc-mappings.json resource: the raw model and pose
 * animation IDs a named NPC had in the 2005-era cache. Generated by the
 * dev-only NpcMappingGenerator tool; deserialized with Gson at plugin startup.
 */
@Getter
public class RetroNpcMappingEntry
{
	private String name;
	private RetroNpcCategory category;
	private int[] modelIds;
	private int idleAnim = -1;
	private int walkAnim = -1;

	// Model resize in 1/128ths, as the 2005 client applied it. The modern client scales an NPC
	// from its own composition, which does not apply to substituted geometry, so the retro
	// values have to be carried and applied by hand.
	private int scaleXZ = 128;
	private int scaleY = 128;

	// Recolor pairs from npc.dat opcode 40, parallel arrays. The 2005 client gave same-mesh NPC
	// variants their color here rather than with separate models, so this is what separates a
	// retro baby blue dragon from a plain one - both are mesh 2998.
	private short[] originalColors;
	private short[] replacementColors;

	// No-arg constructor for Gson
	public RetroNpcMappingEntry()
	{
	}

	public RetroNpcMappingEntry(String name, RetroNpcCategory category, int[] modelIds, int idleAnim, int walkAnim,
		int scaleXZ, int scaleY, short[] originalColors, short[] replacementColors)
	{
		this.name = name;
		this.category = category;
		this.modelIds = modelIds;
		this.idleAnim = idleAnim;
		this.walkAnim = walkAnim;
		this.scaleXZ = scaleXZ;
		this.scaleY = scaleY;
		this.originalColors = originalColors;
		this.replacementColors = replacementColors;
	}

}

