@Slf4j
@PluginDescriptor(
	name = "Retro NPC Swapper",
	description = "Swaps modern NPC models and animations to their 2004/2005 retro variants, using the live cache where those assets survive and a bundled 2005 set where they do not.",
	tags = {"npc", "retro", "swapper", "model", "animation", "cache"}
)
public class RetroNpcSwapperPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RetroNpcConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private RetroModelCache modelCache;

	@Inject
	private ScheduledExecutorService executor;

	/** Where injected geometry comes from. Swappable so the delivery mechanism can change later. */
	private final RetroAssetSource assetSource = new ClasspathAssetSource();

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InteractHighlightCompat interactHighlight;

	@Inject
	private RetroInteractHighlightOverlay interactHighlightOverlay;

	@Inject
	private InteractTargetTracker targetTracker;

	@Inject
	private RetroNpcOutliner outliner;

	// Original pose/movement animations per swapped NPC, keyed by NPC index
	private final Map<Integer, OriginalNpcState> originalNpcState = new HashMap<>();

	/** The renderer 117 HD registers by default; its legacy renderer lives in a sibling package. */
	private static final String HD_ZONE_RENDERER_PACKAGE = "rs117.hd.renderer.zone.";

	private static final String HD_PLUGIN_CLASS = "rs117.hd.HdPlugin";

	// Our decorator, while it owns the client's draw callbacks slot
	private RetroDrawCallbacks wrapper;

	// Class of the last renderer attach() declined, so the decline is logged once rather than per tick
	private String declinedHost;

	// Resolved once - the plugin list does not change identity, and attach() is polled per tick
	private Plugin gpuPlugin;

	// Whether we are currently drawing Interact Highlight's NPC outlines in its place
	private boolean outlineTakeover;

	/**
	 * The in-flight bundle read, so shutDown can cancel it.
	 *
	 * <p>Volatile because startUp and shutDown are not guaranteed to be the same thread.
	 */
	private volatile Future<?> bundleLoad;

	/**
	 * Whether this plugin is still running, read by anything coming back from another thread.
	 *
	 * <p>Volatile for real here rather than defensively: this is written in shutDown and read on
	 * the executor's thread. Cancelling a task cannot stop one already past its own read, nor a
	 * {@code clientThread} runnable it has already queued, so the flag is what actually closes the
	 * window - cancel only keeps a task that never started from starting.
	 */
	private volatile boolean active;

	@Override
	protected void startUp() throws Exception
	{
		log.info("Retro NPC Swapper started");
		active = true;
		migrateLegacyToggles();
		loadMappings();
		loadAssetBundle();
		clientThread.invoke(() ->
		{
			// A session that died while suppressing left Interact Highlight's NPC outlines off.
			// Put them back before attach() decides whether to suppress again.
			interactHighlight.restoreStaleStash();
			recheckLoadedNpcs();
			attach();
		});
	}

	/**
	 * Carries saved values across from config keys that have been replaced.
	 */
	private void migrateLegacyToggles()
	{
		migrateLegacyToggle(configManager, RetroNpcConfig.LEGACY_HILL_GIANTS,
			RetroNpcConfig.SWAP_GIANTS);
	}

	/**
	 * Hands a retired key's saved value to the toggles that replaced it.
	 *
	 * <p>Renaming a config key silently resets whatever the user had chosen, so the old key is read
	 * once and its value handed on. Only ever writes a key that has no value of its own, so a user
	 * who has already set the new toggles is never overwritten - which also makes this safe to run
	 * on every start. The old key is cleared afterward, so the migration happens once and leaves no
	 * orphan behind.
	 *
	 * <p>Takes the manager rather than reading the field so it can be driven directly from a test.
	 * There is no cache or client involved here, only ConfigManager calls, so that is the whole of
	 * what the behavior needs to be checked against.
	 */
	static void migrateLegacyToggle(ConfigManager configManager, String legacyKey, String... newKeys)
	{
		String legacy = configManager.getConfiguration(RetroNpcConfig.GROUP, legacyKey);

		if (legacy == null)
		{
			return;
		}

		for (String key : newKeys)
		{
			if (configManager.getConfiguration(RetroNpcConfig.GROUP, key) == null)
			{
				configManager.setConfiguration(RetroNpcConfig.GROUP, key, Boolean.parseBoolean(legacy));
			}
		}

		configManager.unsetConfiguration(RetroNpcConfig.GROUP, legacyKey);
		log.debug("Migrated {}={} to {}", legacyKey, legacy, String.join(", ", newKeys));
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Retro NPC Swapper stopped");
		active = false;

		// The executor is RuneLite's own and is not ours to shut down, but the read we put on it is.
		// Cancelling does not interrupt one already in progress - hence the active flag it also
		// checks - it only keeps a queued one from ever starting.
		Future<?> load = bundleLoad;
		if (load != null)
		{
			load.cancel(false);
			bundleLoad = null;
		}

		clientThread.invoke(() ->
		{
			// detach() stands the Interact Highlight takeover down as part of dropping the wrapper
			detach();
			resetAllModifiedNpcs();
			modelCache.clear();
		});
	}

	private void loadMappings() throws IOException
	{
		try (InputStream in = RetroNpcSwapperPlugin.class.getResourceAsStream("npc-mappings.json"))
		{
			// The resource is bundled with the plugin, so a miss is a build defect;
			// fail startup loudly rather than silently swapping nothing.
			if (in == null)
			{
				throw new IOException("npc-mappings.json resource is missing");
			}

			List<RetroNpcMappingEntry> entries = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8),
				new TypeToken<List<RetroNpcMappingEntry>>() {}.getType());
			if (entries == null || entries.isEmpty())
			{
				throw new IOException("npc-mappings.json resource is empty or malformed");
			}

			RetroNpcMapping.load(entries);
			log.info("Loaded {} retro NPC mappings", entries.size());
		}
	}

	@Provides
	RetroNpcConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RetroNpcConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (interactHighlight.isUserOverride(event))
		{
			// The user turned Interact Highlight's NPC outlines back on themselves. Hand them back
			// rather than fighting over the setting.
			log.debug("Interact Highlight NPC outlines re-enabled by the user; turning the fix off");
			// Deferred rather than done here: standing down writes config, and doing that from
			// inside a ConfigChanged dispatch would post a nested one
			final String changedKey = event.getKey();
			clientThread.invoke(() ->
			{
				// optOut() has to clear the suppression before the write below, or
				// the ConfigChanged it posts comes back through syncInteractHighlight() into
				// restore(), which would put the stash back over the value the user just chose.
				interactHighlight.optOut(changedKey);

				// Untick the compatibility checkbox when user wants `Interact Highlight` plugin settings re-enabled
				configManager.setConfiguration(RetroNpcConfig.GROUP,
					RetroNpcConfig.OVERRIDE_INTERACT_HIGHLIGHT, false);
				syncInteractHighlight();
			});
			return;
		}

		if (!RetroNpcConfig.GROUP.equals(event.getGroup()) || InteractHighlightCompat.isStashKey(event.getKey()))
		{
			// Stash keys are our own bookkeeping, not a setting the user changed
			return;
		}

		// Refresh active NPC visual overrides when configuration options change
		clientThread.invoke(() ->
		{
			recheckLoadedNpcs();
			syncInteractHighlight();
		});
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		processNpc(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		// A transform gives the NPC a different id, which the spawn-time build never saw.
		// Without reprocessing here the substitution silently stops for that NPC.
		processNpc(event.getNpc());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		targetTracker.onGameTick();

		// Cheap guard: the GPU plugin and 117 HD set and clear the draw callbacks slot
		// unconditionally, so re-take it whenever we have lost it. Covers orderings PluginChanged
		// misses - including 117 HD restarting itself on a settings change, which installs a new
		// renderer without posting any plugin event.
		if (wrapper == null || client.getDrawCallbacks() != wrapper)
		{
			attach();
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (event.getPlugin() instanceof GpuPlugin || isHdPlugin(event.getPlugin()))
		{
			// attach() declines on its own when no supported renderer is holding the slot. 117 HD
			// installs its renderer asynchronously once GL is up, so the per-tick guard is what
			// usually catches it; this just avoids waiting a tick when it is already there.
			clientThread.invoke(this::attach);
		}
		else if (interactHighlight.isInteractHighlightPlugin(event.getPlugin()))
		{
			// Its startUp re-registers its overlay, so the suppression has to be re-applied
			clientThread.invoke(this::syncInteractHighlight);
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// Config is per profile, so the new profile has its own Interact Highlight settings and
		// none of the stash written under the old one. Drop the takeover outright rather than
		// letting syncInteractHighlight see no change and leave the new profile unsuppressed -
		// that would put its outlines back while ours were still drawing.
		clientThread.invoke(() ->
		{
			interactHighlight.forget();
			overlayManager.remove(interactHighlightOverlay);
			outliner.clear();
			outlineTakeover = false;

			interactHighlight.restoreStaleStash();
			syncInteractHighlight();
		});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		targetTracker.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		targetTracker.onInteractingChanged(event);
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		targetTracker.onActorDespawned(event.getPlayer());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		targetTracker.onActorDespawned(npc);
		if (npc != null)
		{
			// Only per-NPC bookkeeping is dropped. The cache's substitution memo is keyed by NPC
			// id, not index, and is shared by every instance of that type, so it is left alone.
			originalNpcState.remove(npc.getIndex());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) actor;

		// Eligibility (wrapper attached, safety settings, category toggles) is decided in
		// processNpc, which maintains the cache's memo. Gating on the same memo keeps animation
		// overrides tied to the model actually being substituted - a vanilla model playing a
		// 2005 sequence renders distorted, since those sequences are keyed to 2005 framemaps.
		if (!modelCache.isSubstituted(npc.getId()))
		{
			return;
		}

		RetroNpcData data = RetroNpcMapping.get(npc.getId(), npc.getName());
		if (data == null)
		{
			return;
		}

		int anim = npc.getAnimation();

		if (anim == -1)
		{
			// Animation finished - re-enforce retro pose animations (idle / walk)
			applyRetroSwap(npc, data);
			return;
		}

		// Guard against re-triggering if current animation is already the retro target animation
		if (data.isRetroAttackAnimation(anim) || anim == data.getDefendAnimationId()
			|| anim == data.getDeathAnimationId() || anim == data.getMiscAnimationId())
		{
			return;
		}

		// Match modern combat animations using Category-Scoped Data Sets
		if (data.isDeathAnimation(anim))
		{
			log.debug("SWAPPING DEATH ANIMATION for NPC '{}' (ID: {}): {} -> {}", npc.getName(), npc.getId(), anim, data.getDeathAnimationId());
			npc.setAnimation(data.getDeathAnimationId());
		}
		else if (data.isDefendAnimation(anim))
		{
			log.debug("SWAPPING DEFEND ANIMATION for NPC '{}' (ID: {}): {} -> {}", npc.getName(), npc.getId(), anim, data.getDefendAnimationId());
			npc.setAnimation(data.getDefendAnimationId());
		}
		else if (data.isAttackAnimation(anim))
		{
			// Per animation rather than per NPC: one that fights in several styles has a 2005 attack
			// for each
			int retroAttack = data.getAttackAnimationFor(anim);
			log.debug("SWAPPING ATTACK ANIMATION for NPC '{}' (ID: {}): {} -> {}", npc.getName(), npc.getId(), anim, retroAttack);
			npc.setAnimation(retroAttack);
		}
		else if (data.isMiscAnimation(anim))
		{
			// An animation the NPC did not have in 2005 at all, so there is nothing to swap it for
			// and it cannot be left alone either - it is keyed to the modern framemap, which does
			// not fit the retro mesh. Standing still is what 2005 looked like.
			log.debug("SWAPPING MODERN-ONLY ANIMATION for NPC '{}' (ID: {}): {} -> {}", npc.getName(), npc.getId(), anim, data.getMiscAnimationId());
			npc.setAnimation(data.getMiscAnimationId());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGING_IN
			|| gameStateChanged.getGameState() == GameState.HOPPING)
		{
			originalNpcState.clear();
			targetTracker.reset();
		}
		else if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::recheckLoadedNpcs);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.INSIDE_WILDERNESS)
		{
			clientThread.invoke(this::recheckLoadedNpcs);
		}
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		clientThread.invoke(this::recheckLoadedNpcs);
	}

	/**
	 * Checks if retro NPC swapping should be disabled due to safety settings
	 * (e.g. on a PvP world or inside the Wilderness).
	 */
	private boolean isSafetyDisabled()
	{
		if (config.disablePvpWorld() && client.getWorldType() != null && WorldType.isPvpWorld(client.getWorldType()))
		{
			return true;
		}
		if (config.disableWilderness() && client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1)
		{
			return true;
		}
		return false;
	}

	/**
	 * Evaluates an NPC to check if it should be swapped to its retro variant.
	 */
	private void processNpc(NPC npc)
	{
		if (npc == null)
		{
			return;
		}

		RetroNpcData data = RetroNpcMapping.get(npc.getId(), npc.getName());

		// Animation overrides are gated on substitution being live. Without the wrapper the
		// model stays vanilla, and a modern-rigged model playing a 2005 sequence - which is
		// keyed to 2005 framemaps - renders distorted rather than retro.
		//
		// Verify if category toggle is enabled in configuration
		if (wrapper == null || isSafetyDisabled() || data == null || !isCategoryEnabled(data.getCategory()))
		{
			modelCache.clearSubstituted(npc.getId());
			resetNpc(npc);
			return;
		}

		// Build the replacement geometry here, on the client thread, so the draw callback
		// only ever does a map lookup. Nothing else happens if that fails: an NPC left on its
		// vanilla model must keep its vanilla animations too, for the reason above. The bundle
		// loads off-thread, so this is not a rare path - every giant, guard, dragon and demon
		// already on screen when the plugin starts comes through here before it lands, and
		// recheckLoadedNpcs picks them up once it does.
		if (!modelCache.ensureBuilt(npc.getId(), data))
		{
			modelCache.clearSubstituted(npc.getId());
			resetNpc(npc);
			return;
		}

		modelCache.setSubstituted(npc.getId());
		applyRetroSwap(npc, data);
	}

	/**
	 * Applies retro animation overrides to the given NPC.
	 *
	 * <p>Geometry is substituted per NPC at draw time by {@link RetroDrawCallbacks}
	 */
	private void applyRetroSwap(NPC npc, RetroNpcData data)
	{
		// Save original animation states before overriding
		originalNpcState.computeIfAbsent(npc.getIndex(), idx -> OriginalNpcState.capture(npc));

		log.debug("INTERCEPTED NPC: name='{}', id={}, index={}, category={}",
			npc.getName(), npc.getId(), npc.getIndex(), data.getCategory());

		// Apply idle animation override from 2005 cache definition
		if (data.getIdleAnimationId() != -1)
		{
			log.debug("SWAPPING IDLE ANIMATION for NPC '{}': orig={} -> retro={}",
				npc.getName(), npc.getIdlePoseAnimation(), data.getIdleAnimationId());
			npc.setIdlePoseAnimation(data.getIdleAnimationId());
			npc.setPoseAnimation(data.getIdleAnimationId());
			npc.setIdleRotateLeft(data.getIdleAnimationId());
			npc.setIdleRotateRight(data.getIdleAnimationId());
		}

		// Apply walking animation override from 2005 cache definition
		if (data.getWalkAnimationId() != -1)
		{
			log.debug("SWAPPING WALK ANIMATION for NPC '{}': orig={} -> retro={}",
				npc.getName(), npc.getWalkAnimation(), data.getWalkAnimationId());
			npc.setWalkAnimation(data.getWalkAnimationId());
			npc.setWalkRotate180(data.getWalkAnimationId());
			npc.setWalkRotateLeft(data.getWalkAnimationId());
			npc.setWalkRotateRight(data.getWalkAnimationId());
			npc.setRunAnimation(data.getWalkAnimationId());
		}
	}

	/**
	 * Resets an NPC back to its original visual state.
	 */
	private void resetNpc(NPC npc)
	{
		OriginalNpcState state = originalNpcState.remove(npc.getIndex());
		if (state == null)
		{
			return;
		}

		log.debug("Resetting NPC visuals for: {} (ID: {})", npc.getName(), npc.getId());

		// Only animations need restoring - the composition was never modified, and dropping the
		// NPC id from the cache's memo is what reverts its models on the next frame drawn.
		state.restore(npc);
	}

	/**
	 * Checks if a specific NPC category toggle is enabled in config.
	 */
	private boolean isCategoryEnabled(RetroNpcCategory category)
	{
		if (category == null)
		{
			return false;
		}

		switch (category)
		{
			case CHICKENS:
				return config.swapChickens();
			case COWS:
				return config.swapCows() && injectionEnabled();
			case HELLHOUNDS:
				// Mesh 2997 and sequences 157-161 both survive intact, so the cache path draws it
				return config.swapHellhounds();
			case GIANT_RATS:
				// Mesh 2959 and sequences 137-141 both survive intact, so the cache path draws it
				return config.swapGiantRats();
			case SCORPIONS:
				// Injectionis required for large scorpions
				return config.swapScorpions() && injectionEnabled();
			case SMALL_SCORPIONS:
				// Mesh 2968 and sequences 269-273 survive intact, so the cache path draws it
				return config.swapScorpions();
			case GOBLINS:
				return config.swapGoblins();
			case SKELETONS:
				return config.swapSkeletons();
			case SKELETON_MAGES:
				// Shares the Skeletons toggle. The mage is human kit, half of whose parts are gone from
				// the live cache, so like the guards it can only be drawn from the bundle
				return config.swapSkeletons() && injectionEnabled();
			case ZOMBIES:
				return config.swapZombies();
			case HILL_GIANTS:
				// The body survives and the Jogre head stands in for the one that does not, so this
				// one renders on either path - the injection toggle just decides which
				return config.swapGiants();
			case FIRE_GIANTS:
			case ICE_GIANTS:
			case MOSS_GIANTS:
				// Their 2005 heads are gone from the live cache, so the cache-backed path would load
				// unrelated geometry. Only the bundle can supply them.
				return config.swapGiants() && injectionEnabled();
			case CYCLOPS:
				return config.swapCyclops() && injectionEnabled();
			case GUARDS:
				// Three of the nine kit parts are gone from the live cache, and the six that remain
				// were re-bound to a different rig, so both the geometry and the animation have to
				// come from the bundle
				return config.swapGuards() && injectionEnabled();
			case GHOSTS:
				return config.swapGhosts();
			case ADULT_DRAGONS:
			case BABY_DRAGONS:
				// The adult mesh has no usable live counterpart at all - the ids resolve, but to
				// unrelated geometry. The baby mesh survives, but both had their frames re-authored,
				// so both need the injected path to be animated from the 2005 data
				return config.swapDragons() && injectionEnabled();
			case LESSER_DEMONS:
			case GREATER_DEMONS:
			case BLACK_DEMONS:
				return config.swapDemons() && injectionEnabled();
			case IMPS:
				// The imp mesh survives, so this is not about geometry: the frames behind its
				// sequence ids were re-authored for the modern rig, and applying the 2005 ones
				// means skinning the model ourselves
				return config.swapImps() && injectionEnabled();
			default:
				return false;
		}
	}

	/**
	 * Whether the categories that can only be drawn from the bundle are allowed to draw at all.
	 *
	 * <p>The config value rather than the cache's copy of it. The two are the same by the time this
	 * decides anything: recheckLoadedNpcs hands the config value to the cache, and processNpc will
	 * not reach here until attach() has run, which happens after that on every path.
	 */
	private boolean injectionEnabled()
	{
		return config.useInjectionPipeline();
	}

	/**
	 * Reads the injected asset bundle off the client thread and publishes it back onto it.
	 *
	 * <p>Decompressing the bundle is quick, but it is still disk IO, and startUp must not block on
	 * it - so this is fire-and-forget. Everything downstream treats an absent bundle as "no
	 * injected assets", which is why nothing has to wait for this to finish.
	 */
	private void loadAssetBundle()
	{
		bundleLoad = executor.submit(() ->
		{
			if (!active)
			{
				return;
			}

			RetroAssetBundle bundle;
			try
			{
				bundle = assetSource.load();
			}
			catch (IOException ex)
			{
				// A bundle that exists but will not read is worth saying out loud, unlike one that
				// is simply absent - it means a stale or truncated resource, not a build without
				// injected assets
				log.warn("Could not read the retro asset bundle; injected geometry is unavailable", ex);
				return;
			}

			if (bundle.isEmpty())
			{
				log.debug("No retro asset bundle present");
				return;
			}

			clientThread.invoke(() ->
			{
				// A read that finishes after shutDown must not put the bundle back into a cache
				// that was just cleared, nor sweep the scene on behalf of a plugin that is no
				// longer running
				if (!active)
				{
					log.debug("Retro asset bundle finished reading after shutdown; dropping it");
					return;
				}

				modelCache.setBundle(bundle);

				// The load is off-thread, so NPCs are usually already on screen by the time it
				// lands - and setBundle only drops what was built, it does not rebuild. Without
				// this they stay vanilla until they happen to respawn, which for the guards
				// standing where you log in could be a long time.
				recheckLoadedNpcs();
			});
		});
	}

	/**
	 * Re-evaluates all currently loaded scene NPCs against active configuration toggles.
	 */
	private void recheckLoadedNpcs()
	{
		// Cheap and idempotent, and this runs on every path that could have changed the setting -
		// startup, config change, world change, a landed bundle, and attach
		modelCache.setUseInjectionPipeline(config.useInjectionPipeline());

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		for (NPC npc : worldView.npcs())
		{
			if (npc != null)
			{
				processNpc(npc);
			}
		}
	}

	/**
	 * Resets all modified NPCs in the scene back to default visuals upon plugin shutdown.
	 */
	private void resetAllModifiedNpcs()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			WorldView worldView = client.getTopLevelWorldView();
			if (worldView != null)
			{
				for (NPC npc : worldView.npcs())
				{
					if (npc != null && originalNpcState.containsKey(npc.getIndex()))
					{
						resetNpc(npc);
					}
				}
			}
		}

		originalNpcState.clear();
	}

	/**
	 * Takes over the client's draw callbacks slot by wrapping whichever supported renderer holds it:
	 * the GPU plugin, or 117 HD's zone renderer.
	 *
	 * <p>Declines for anything else - no renderer at all, an unknown one, or 117 HD's legacy
	 * renderer. That last one is not an oversight: it implements no {@code drawTemp} and does not run
	 * the ZBUF path, so wrapping it would substitute nothing while still letting processNpc apply
	 * 2005 animations to modern rigs. Must be called on the client thread.
	 */
	private void attach()
	{
		DrawCallbacks current = client.getDrawCallbacks();
		if (wrapper != null && current == wrapper)
		{
			return;
		}

		// We are not the registered callbacks anymore; drop the stale reference before
		// deciding whether we can retake the slot
		boolean wasAttached = wrapper != null;
		wrapper = null;

		if (isSupportedHost(current, findGpuPlugin()))
		{
			RetroDrawCallbacks callbacks = new RetroDrawCallbacks(current, this::substitute);
			client.setDrawCallbacks(callbacks);
			wrapper = callbacks;
			declinedHost = null;
			log.debug("Attached retro draw callbacks over {}", current.getClass().getName());
		}
		else if (current != null && !current.getClass().getName().equals(declinedHost))
		{
			// Polled every tick while detached, so only said once per renderer
			declinedHost = current.getClass().getName();
			log.debug("Draw callbacks held by unsupported renderer {}; skipping model swap", declinedHost);
		}

		// Only on a real transition - the per-tick guard calls this repeatedly while detached,
		// and re-processing the whole scene every tick would be wasteful
		if (wasAttached == (wrapper == null))
		{
			recheckLoadedNpcs();
			syncInteractHighlight();
		}
	}

	/**
	 * Hands the draw callbacks slot back to the GPU plugin. Must be called on the client thread.
	 */
	private void detach()
	{
		if (wrapper != null && client.getDrawCallbacks() == wrapper)
		{
			// Restore the delegate, never null - nulling the slot would leave the GPU plugin
			// running with no callbacks registered
			client.setDrawCallbacks(wrapper.getDelegate());
			log.debug("Detached retro draw callbacks");
		}
		else if (wrapper != null)
		{
			// Something else holds the slot. If it wrapped our wrapper, that stale decorator
			// stays in its chain - harmless once the cache's memo is cleared (every
			// substitution then falls through to the vanilla model), but worth saying.
			log.debug("Draw callbacks slot no longer ours at detach; leaving it untouched");
		}
		wrapper = null;

		// Nothing is being swapped anymore, so Interact Highlight's own outlines are correct again
		syncInteractHighlight();
	}

	/**
	 * Whether {@code current} is a renderer {@link RetroDrawCallbacks} can substitute models through.
	 *
	 * <p>117 HD is a Plugin Hub plugin loaded in its own classloader, so it is recognized by class
	 * name alone - there is no compile or runtime dependency on it, and with it absent nothing here
	 * matches. The zone renderer package is allowlisted rather than the legacy one denylisted, so a
	 * renderer 117 HD adds or renames later is declined instead of wrapped blind.
	 */
	static boolean isSupportedHost(DrawCallbacks current, Plugin gpu)
	{
		return current != null && (current == gpu || isHdZoneRenderer(current.getClass().getName()));
	}

	static boolean isHdZoneRenderer(String className)
	{
		return className.startsWith(HD_ZONE_RENDERER_PACKAGE);
	}

	private static boolean isHdPlugin(Plugin plugin)
	{
		return plugin != null && HD_PLUGIN_CLASS.equals(plugin.getClass().getName());
	}

	private Plugin findGpuPlugin()
	{
		if (gpuPlugin == null)
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (plugin instanceof GpuPlugin)
				{
					gpuPlugin = plugin;
					break;
				}
			}
		}
		return gpuPlugin;
	}

	/**
	 * Takes over Interact Highlight's NPC outlines, or hands them back.
	 *
	 * <p>Only worth doing while geometry is actually being substituted - with no wrapper attached
	 * the vanilla model is what gets drawn, and that plugin's own outline already fits it. Must be
	 * called on the client thread.
	 */
	private void syncInteractHighlight()
	{
		boolean takeOver = config.overrideInteractHighlight()
			&& wrapper != null
			&& interactHighlight.isInteractHighlightActive();

		if (takeOver == outlineTakeover)
		{
			return;
		}

		if (takeOver)
		{
			interactHighlight.suppress();
			overlayManager.add(interactHighlightOverlay);
		}
		else
		{
			interactHighlight.restore();
			overlayManager.remove(interactHighlightOverlay);
			outliner.clear();
		}

		// Last, so a failure to write config does not leave us recorded as having taken over
		outlineTakeover = takeOver;
	}

	/**
	 * Supplies retro geometry for an NPC being drawn, or null to let the vanilla model through.
	 *
	 * <p>Runs per NPC per frame, so it does map lookups only - eligibility is decided in
	 * {@link #processNpc} and the geometry is built by {@link RetroModelCache} ahead of time.
	 */
	private Model substitute(NPC npc, Model vanilla)
	{
		// The posed model is shared and only valid until the next applyTransformations call. It is
		// handed straight to the delegate and uploaded before anything else can run, which is what
		// makes that safe here. Returns null for an NPC that is not being substituted.
		return modelCache.pose(npc);
	}
}
